window.SURPRISE_STORIES=[{"id":"lion-mouse","t":"The Lion and the Mouse","l":1,"ic":"🦁","p":["A big lion was sleeping under a tree. A little mouse ran across his nose by mistake.","The lion woke up. He caught the mouse with his huge paw. “I will eat you!” he roared.","“Please let me go,” said the mouse. “One day I will help you.”","The lion laughed. “How can a tiny mouse help a king like me?” But he opened his paw, and the mouse ran away.","A few days later, hunters caught the lion in a strong net. He roared and pulled, but he could not escape.","The little mouse heard him. She ran to the net and started to bite the ropes with her sharp teeth.","Soon there was a big hole in the net, and the lion was free.","“You laughed at me,” said the mouse, “but now you see that a little friend can be a great friend.”"],"g":{"paw":"مخلب / كفّ الحيوان","roared":"زأر","tiny":"صغير جداً","hunters":"صيّادون","net":"شبكة","escape":"يهرب","bite":"يقضم / يعض"},"m":["Kindness is never wasted, and small friends can be a big help.","المعروف لا يضيع، والصديق الصغير قد يكون عوناً كبيراً."],"q":[["What did the lion want to do with the mouse at first?",["Eat it","Play with it","Ask it for help"],0],["How did the mouse save the lion?",["She called other animals","She bit the ropes of the net","She scared the hunters"],1],["Why did the lion laugh?",["The mouse told a joke","He did not believe a tiny mouse could help him","He was happy to be free"],1]]},{"id":"tortoise-hare","t":"The Tortoise and the Hare","l":1,"ic":"🐢","p":["A hare always laughed at a tortoise. “You are so slow!” he said. “You walk like a stone.”","The tortoise smiled. “Let’s have a race,” he said. “We will see who wins.”","All the animals came to watch. The race began, and the hare ran very fast. Soon the tortoise was far behind.","The hare looked back. “I have lots of time,” he thought. “I will sleep for a while under this tree.”","The tortoise did not stop. Step by step, slowly and steadily, he walked past the sleeping hare.","When the hare woke up, the sun was going down. He ran as fast as he could, but it was too late.","The tortoise was already at the finish line. All the animals cheered for him.","The hare learned an important lesson that day."],"g":{"race":"سباق","behind":"خلف","steadily":"بثبات","finish line":"خط النهاية","cheered":"هتفوا / شجّعوا","lesson":"درس"},"m":["Slow and steady wins the race.","الثبات والمثابرة يغلبان السرعة والغرور."],"q":[["Why did the hare stop during the race?",["He was hurt","He wanted to sleep","He lost his way"],1],["How did the tortoise walk?",["Fast and carelessly","Slowly and steadily","He did not walk"],1],["Who won the race?",["The hare","Nobody","The tortoise"],2]]},{"id":"boy-wolf","t":"The Boy Who Cried Wolf","l":1,"ic":"🐺","p":["A young shepherd watched his sheep on a hill near the village. Every day was quiet, and he was bored.","One day he had an idea. He shouted, “Wolf! Wolf! A wolf is eating the sheep!”","The villagers ran up the hill to help him. But there was no wolf. The boy laughed and laughed.","A few days later, he did the same thing again. Again the villagers came, and again there was no wolf.","Then one evening, a real wolf came out of the forest. It ran toward the sheep.","The boy was very frightened. “Wolf! Wolf!” he cried. “Please help me!”","But this time nobody came. “He is lying again,” the villagers said.","The wolf scattered the sheep, and the boy learned a hard lesson."],"g":{"shepherd":"راعٍ","bored":"يشعر بالملل","villagers":"أهل القرية","real":"حقيقي","frightened":"خائف","lying":"يكذب","scattered":"فرّق / بعثر"},"m":["Nobody believes a liar, even when he tells the truth.","الكاذب لا يُصدَّق حتى لو قال الصدق."],"q":[["Why did the boy shout “Wolf!” the first time?",["He saw a wolf","He was bored and wanted fun","His sheep were lost"],1],["What happened when a real wolf came?",["The villagers ran to help","Nobody came to help","The boy caught the wolf"],1],["Why didn’t the villagers come at the end?",["They were asleep","They thought he was lying again","They were afraid of the wolf"],1]]},{"id":"fox-grapes","t":"The Fox and the Grapes","l":1,"ic":"🦊","p":["On a hot day, a hungry fox walked into a garden. He saw some sweet purple grapes hanging high on a vine.","“Those grapes look delicious,” he said. “They are just what I need.”","He jumped up, but he could not reach them. He stepped back, ran, and jumped again. He missed again.","He tried again and again until he was tired and hot.","At last he sat down and looked at the grapes.","“I don’t really want them,” he said as he walked away. “I am sure they are sour.”"],"g":{"hungry":"جائع","vine":"كرمة / عريشة العنب","delicious":"لذيذ","reach":"يصل إلى","missed":"أخطأ / لم يصب","sour":"حامض"},"m":["It is easy to dislike what you cannot have.","من السهل أن تذمّ ما لا تستطيع الحصول عليه."],"q":[["Where were the grapes?",["On the ground","High on a vine","In a basket"],1],["Did the fox reach the grapes?",["Yes, at last","No, never","Yes, with help"],1],["What did the fox say about the grapes at the end?",["They are sweet","They are sour","They are too big"],1]]},{"id":"ant-grasshopper","t":"The Ant and the Grasshopper","l":1,"ic":"🐜","p":["All summer, a little ant worked hard. She carried seeds and food to her home, one by one.","A grasshopper watched her and laughed. “Why are you working so hard? Come and sing and play with me!”","“I am saving food for the winter,” said the ant. “You should do the same.”","“Winter is far away,” said the grasshopper. “We have plenty of food now.” And he kept on singing.","Then winter came. The ground was cold, and there was no food anywhere.","The grasshopper was weak and hungry. He knocked on the ant’s door and asked for some food.","The ant shared a little food with him, but she said, “Next summer, work today for tomorrow.”","The grasshopper never forgot those words."],"g":{"seeds":"بذور","saving":"يدّخر","plenty":"وفرة / كثير","weak":"ضعيف","knocked":"طرق","shared":"شارك / تقاسم"},"m":["Work today and prepare for tomorrow.","اعمل اليوم واستعدّ للغد."],"q":[["What did the ant do in summer?",["She sang and played","She saved food for winter","She slept all day"],1],["What did the grasshopper do in summer?",["He sang and played","He built a house","He collected seeds"],0],["What did the ant tell the grasshopper at the end?",["Go away","Work today for tomorrow","Sing more songs"],1]]},{"id":"crow-pitcher","t":"The Crow and the Pitcher","l":1,"ic":"🐦","p":["It was a very hot summer. There was no rain, and a thirsty crow flew everywhere looking for water.","At last she found a tall pitcher. There was a little water at the bottom, but her beak could not reach it.","She tried to push the pitcher over, but it was too heavy. She almost gave up.","Then she had a clever idea. She picked up a small stone and dropped it into the pitcher.","She dropped another stone, and another. Slowly, the water rose higher and higher.","At last the water reached the top, and the crow drank until she was happy."],"g":{"thirsty":"عطشان","pitcher":"إبريق / جرّة","beak":"منقار","gave up":"استسلم","clever":"ذكي","dropped":"أسقط","rose":"ارتفع"},"m":["When you need something, think of a clever way.","الحاجة أمّ الاختراع؛ فكّر بذكاء تجد الحل."],"q":[["What was the crow looking for?",["Food","Water","Her nest"],1],["Why couldn’t she drink at first?",["The water was too hot","Her beak couldn’t reach the water","The pitcher was closed"],1],["How did she solve the problem?",["She broke the pitcher","She dropped stones into it","She asked for help"],1]]},{"id":"golden-eggs","t":"The Goose That Laid the Golden Eggs","l":2,"ic":"🥚","p":["A poor farmer and his wife had a special goose. Every morning, she laid one egg made of shining gold.","The farmer sold the eggs at the market, and soon he became rich.","But the richer he became, the greedier he became. “One egg a day is too slow,” he said.","“The goose must have lots of gold inside her. If I open her, I can take it all at once!”","So he killed the goose and looked inside. But there was no gold at all. She was just like any other goose.","Now the farmer had no goose and no more golden eggs. He sat down and cried."],"g":{"goose":"إوزّة","laid":"باضت","shining":"لامع","greedier":"أكثر طمعاً","at once":"دفعة واحدة","market":"سوق"},"m":["Greed can make you lose everything.","الطمع يضيّع ما جمع."],"q":[["What was special about the goose?",["It could talk","It laid golden eggs","It was very big"],1],["Why did the farmer kill the goose?",["He was hungry","He wanted all the gold at once","The goose was ill"],1],["What did he find inside the goose?",["A lot of gold","One golden egg","No gold at all"],2]]},{"id":"wind-sun","t":"The North Wind and the Sun","l":2,"ic":"☀️","p":["The North Wind and the Sun had an argument. “I am stronger than you,” said the Wind. “No, I am stronger,” said the Sun.","Just then, they saw a traveler walking on the road. He was wearing a warm coat.","“Let’s have a contest,” said the Sun. “Whoever can make that man take off his coat is the stronger one.”","The Wind went first. He blew hard and cold. But the harder he blew, the tighter the man held his coat.","Then it was the Sun’s turn. The Sun came out and shone gently and warmly.","Soon the traveler felt hot. He smiled, took off his coat, and sat down in the shade of a tree.","The Wind had to agree: the Sun had won the contest."],"g":{"argument":"جدال","traveler":"مسافر","contest":"مسابقة","blew":"هبّ / نفخ","tighter":"بإحكام أكثر","gently":"بلطف","shade":"ظلّ"},"m":["Kindness and gentleness work better than force.","اللين والرفق أقوى من القسوة والعنف."],"q":[["What did the Wind and the Sun argue about?",["Who was older","Who was stronger","Who was faster"],1],["What happened when the Wind blew hard?",["The man took off his coat","The man held his coat tighter","The man ran home"],1],["How did the Sun win?",["By shining gently and warmly","By hiding behind clouds","By blowing cold air"],0]]},{"id":"dog-reflection","t":"The Dog and His Reflection","l":1,"ic":"🐕","p":["A dog found a big piece of meat. He held it in his mouth and ran home happily.","On the way, he crossed a bridge over a calm river. He looked down into the water.","In the water he saw another dog with another piece of meat. It looked even bigger than his!","“I want that meat too,” he thought. He opened his mouth to bark and grab it.","Splash! His own meat fell into the river and disappeared.","The other dog was only his reflection. Now he had nothing at all."],"g":{"meat":"لحم","bridge":"جسر","calm":"هادئ","bark":"ينبح","grab":"ينتزع / يخطف","disappeared":"اختفى","reflection":"انعكاس / خيال في الماء"},"m":["If you want more than you need, you may lose what you have.","من طلب الزيادة بطمع قد يخسر ما في يده."],"q":[["What did the dog have in his mouth?",["A bone","A piece of meat","A ball"],1],["What did he see in the river?",["A real dog","His own reflection","A fish"],1],["What happened when he opened his mouth?",["He caught more meat","His meat fell into the river","He started to swim"],1]]},{"id":"fox-crow","t":"The Fox and the Crow","l":2,"ic":"🧀","p":["A crow found a piece of cheese and flew up to a high branch to eat it.","A fox saw her. He wanted the cheese, so he sat under the tree and began to speak sweetly.","“Good morning, beautiful bird!” he said. “Your feathers are so shiny and your eyes are so bright.”","“I am sure your voice is the most beautiful in the forest. Please sing one song for me!”","The crow was very pleased. She opened her beak to sing — and the cheese fell to the ground.","The fox caught it at once. “Thank you,” he said. “Next time, don’t trust people who praise you too much.”"],"g":{"branch":"غصن","sweetly":"بلطف / بكلام معسول","feathers":"ريش","shiny":"لامع","pleased":"مسرور","praise":"يمدح"},"m":["Be careful of people who flatter you to get something.","احذر ممن يمدحك ليأخذ ما عندك."],"q":[["What did the crow have?",["A piece of cheese","A piece of bread","An apple"],0],["Why did the fox praise the crow?",["He loved her songs","He wanted her cheese","He wanted to be her friend"],1],["What happened when the crow sang?",["The fox clapped","The cheese fell down","She flew away"],1]]},{"id":"town-country-mouse","t":"The Town Mouse and the Country Mouse","l":2,"ic":"🐭","p":["A country mouse invited her cousin from the town to visit. She served simple food: seeds, corn and fresh water.","The town mouse was not impressed. “How can you live like this?” she said. “Come to the town with me. I will show you real food!”","In the town, they went into a big house. On the table there were cakes, cheese and fruit.","But just as they started to eat, the door opened. A cook came in, and the two mice ran and hid.","When it was quiet, they came out again. Then a big cat jumped onto the table! They ran for their lives.","“Goodbye, cousin,” said the country mouse. “You can keep your cakes. I prefer my simple food and my peaceful home.”"],"g":{"cousin":"ابن العم / الخال","served":"قدّم (الطعام)","impressed":"معجب","hid":"اختبأ","for their lives":"هرباً بحياتهم","prefer":"يفضّل","peaceful":"هادئ / آمن"},"m":["A simple life in peace is better than a rich life in fear.","العيش البسيط في أمان خير من الغنى مع الخوف."],"q":[["What food did the country mouse serve?",["Cakes and cheese","Seeds, corn and water","Meat and rice"],1],["What happened in the town house?",["They ate in peace","A cook and a cat scared them","They met many friends"],1],["What did the country mouse decide?",["To stay in the town","To go back to her peaceful home","To buy cakes"],1]]},{"id":"bundle-sticks","t":"The Bundle of Sticks","l":2,"ic":"🪵","p":["An old father had several sons. They were always arguing and fighting with each other.","One day he called them together. He gave them a bundle of sticks tied with a rope. “Try to break it,” he said.","Each son tried with all his strength, but nobody could break the bundle.","Then the father untied the rope and gave each son one stick. “Now break these,” he said. They broke them easily.","“My sons,” said the father, “if you stand together, nobody can break you.","But if you are divided, anyone can break you, one by one.” From that day, the brothers stopped fighting."],"g":{"arguing":"يتجادلون","bundle":"حزمة","tied":"مربوط","strength":"قوة","untied":"فكّ","divided":"متفرّقون / منقسمون"},"m":["Unity is strength.","في الاتحاد قوة."],"q":[["What was the problem with the sons?",["They were lazy","They were always fighting","They were ill"],1],["Could the sons break the bundle?",["Yes, easily","No","Only the oldest son"],1],["What lesson did the father teach?",["Sticks are useful","Together we are strong","Fighting is fun"],1]]},{"id":"emperor-clothes","t":"The Emperor’s New Clothes","l":3,"ic":"👑","p":["Long ago, there was an emperor who loved new clothes more than anything else.","One day, two clever tricksters came to the palace. “We can make the most beautiful cloth in the world,” they said. “But it is magic: foolish people cannot see it.”","The emperor gave them gold, and they pretended to weave all day on empty machines.","He sent his ministers to look. They saw nothing, but they were afraid to look foolish, so they said, “It is wonderful!”","At last the emperor went to see the clothes himself. He saw nothing at all! But he also said, “Magnificent!”","The tricksters pretended to dress him, and the emperor walked through the city in a great parade.","Everyone praised the clothes, because nobody wanted to look foolish.","Then a little child shouted, “But he isn’t wearing anything new at all!” Soon the whole crowd was saying it. The emperor felt ashamed, but he kept walking proudly to the end."],"g":{"emperor":"إمبراطور","tricksters":"محتالون","foolish":"أحمق / غبي","pretended":"تظاهر","weave":"ينسج","magnificent":"رائع / فخم","parade":"موكب","ashamed":"خجلان"},"m":["Have the courage to tell the truth, even when others are afraid.","كن شجاعاً في قول الحق ولو خاف الآخرون."],"q":[["What did the tricksters say about their cloth?",["It was very cheap","Foolish people cannot see it","It was made of gold"],1],["Why did the ministers say the clothes were wonderful?",["They really saw them","They did not want to look foolish","The emperor paid them"],1],["Who told the truth at the parade?",["A minister","A little child","The tricksters"],1]]},{"id":"elves-shoemaker","t":"The Elves and the Shoemaker","l":2,"ic":"👞","p":["There was once a good shoemaker who became very poor. He had only enough leather for one last pair of shoes.","In the evening, he cut the leather and left it on his table. Then he went to bed.","In the morning, he found a beautiful pair of shoes on the table, perfectly made! A customer bought them for a high price.","With the money, he bought leather for two pairs. The next morning, both pairs were ready too.","This happened night after night, and the shoemaker became rich. One night, he and his wife hid and watched.","At midnight, two tiny elves came in. They worked quickly and happily until all the shoes were finished.","“They have helped us so much,” said his wife. “Let’s thank them.” So they made tiny warm clothes for the elves.","The elves were delighted. They put on their new clothes, danced, and left. The shoemaker never forgot their kindness."],"g":{"shoemaker":"إسكافي / صانع أحذية","leather":"جلد","customer":"زبون","elves":"أقزام (مخلوقات خيالية)","delighted":"مسرور جداً","kindness":"لطف / معروف"},"m":["Good deeds deserve thanks; always repay kindness.","الإحسان يُقابَل بالشكر، فردّ المعروف بمثله."],"q":[["What did the shoemaker find in the morning?",["A bag of gold","A finished pair of shoes","A letter"],1],["Who was making the shoes?",["His wife","Two tiny elves","A customer"],1],["How did the shoemaker and his wife thank the elves?",["They gave them money","They made them tiny clothes","They gave them shoes"],1]]},{"id":"stone-soup","t":"Stone Soup","l":2,"ic":"🍲","p":["A tired traveler arrived in a small village. He was hungry, but the villagers said, “We have no food to share.”","So he put a big pot of water on a fire in the square. Then he dropped a smooth stone into it.","“What are you cooking?” asked a curious boy. “Stone soup,” said the traveler. “It is delicious, but a carrot would make it even better.”","The boy ran home and came back with a carrot.","Soon a woman brought an onion. A farmer brought some potatoes. Another man brought salt and a little meat.","Little by little, the pot was filled with good things, and it smelled wonderful.","That evening, the whole village sat together and enjoyed a delicious soup.","“Amazing!” they said. “Soup from a stone!” The traveler smiled. He knew the real secret was sharing."],"g":{"traveler":"مسافر","pot":"قِدر","square":"ساحة","smooth":"أملس","curious":"فضولي","little by little":"شيئاً فشيئاً","sharing":"المشاركة"},"m":["When everyone shares a little, there is enough for all.","إذا شارك كلّ واحد بالقليل كفى الجميع."],"q":[["What did the traveler put in the pot first?",["A carrot","A stone","Some meat"],1],["Who brought the carrot?",["A curious boy","The farmer","The traveler"],0],["What was the real secret of the soup?",["The magic stone","Sharing","A special pot"],1]]},{"id":"king-midas","t":"King Midas and the Golden Touch","l":3,"ic":"✨","p":["King Midas was very rich, but he always wanted more gold. One day a visitor offered him one wish.","“I wish that everything I touch turns into gold!” said the king. “Your wish is granted,” said the visitor.","The king was excited. He touched a chair, and it became gold. He touched a flower, and it became gold too!","Then he sat down to eat. But when he picked up some bread, it turned into hard gold. He could not eat or drink anything.","Just then his little daughter ran to hug him. As soon as he touched her, she turned into a golden statue!","The king cried. “Please take this wish away! I don’t want gold. I want my daughter back!”","The visitor told him to wash his hands in the river. The king ran there and washed. Then he poured water on his daughter, and she came back to life.","From that day, King Midas understood that the most precious things in life are not made of gold."],"g":{"wish":"أمنية","granted":"مُجاب / مُحقَّق","touch":"يلمس","statue":"تمثال","poured":"سكب","precious":"ثمين"},"m":["Love and family are worth more than all the gold in the world.","المحبة والأهل أثمن من كل ذهب الدنيا."],"q":[["What was the king’s wish?",["To be very strong","That everything he touched would become gold","To live forever"],1],["Why couldn’t the king eat?",["His food turned into gold","He was not hungry","There was no food"],0],["What did the king learn?",["Gold is the most important thing","The most precious things are not gold","Wishes are always good"],1]]},{"id":"juha-donkey","t":"Juha, His Son and the Donkey","l":2,"ic":"🐴","p":["One day, Juha and his son went to the market with their donkey. Juha rode the donkey, and his son walked beside him.","Some people said, “Look at that man! He rides comfortably while the poor boy walks.” So Juha got down, and his son rode.","Soon other people said, “What a rude boy! He rides while his old father walks.”","So they both rode the donkey. Then people shouted, “Poor donkey! Two people on one small animal!”","So they both got down and walked next to the donkey. Now people laughed. “How silly! They have a donkey, and nobody rides it!”","Juha turned to his son and smiled. “You see, my son? Whatever we do, someone will complain.”","“Do what is right and wise,” said Juha, “and don’t worry too much about what everyone says.”"],"g":{"beside":"بجانب","comfortably":"براحة","rude":"قليل الأدب","silly":"سخيف","complain":"يشتكي / ينتقد","wise":"حكيم"},"m":["You cannot please everyone, so do what is right.","رضا الناس غاية لا تُدرك؛ فافعل الصواب."],"q":[["Where were Juha and his son going?",["To the market","To school","To the mosque"],0],["What did people say when both of them rode the donkey?",["What a strong donkey","Poor donkey!","Well done!"],1],["What did Juha learn?",["Donkeys are lazy","You cannot please everyone","Walking is bad"],1]]},{"id":"juha-nail","t":"Juha’s Nail","l":2,"ic":"🔨","p":["Juha needed money, so he decided to sell his house. A rich man wanted to buy it, but he offered a very low price.","Juha agreed, but he had one condition. “There is a nail in the wall of the living room,” he said. “The nail will still belong to me.”","The buyer laughed. “Just one old nail? No problem!” And he signed the agreement.","A few days later, Juha knocked on the door. “I have come to visit my nail,” he said, and he hung his coat on it.","The next day he came again and hung a heavy bag on the nail. The next week, he came at lunchtime and sat beside his nail for hours.","Every day Juha found a new reason to visit his nail, and he never left early.","At last the rich man could not stand it anymore. He gave the house back to Juha and left.","Juha smiled. A small nail had won the whole house."],"g":{"offered":"عرض","condition":"شرط","nail":"مسمار","belong":"يعود ملكه لـ","signed":"وقّع","hung":"علّق","stand":"يتحمّل"},"m":["Read every condition carefully before you agree.","اقرأ الشروط جيداً قبل أن توافق."],"q":[["What did Juha keep when he sold his house?",["The door","A nail in the wall","The garden"],1],["Why did Juha visit the house every day?",["To clean it","To visit his nail","To pay rent"],1],["What happened at the end?",["The rich man gave the house back","Juha bought a new house","The nail broke"],0]]}];
